<script>
document.addEventListener('DOMContentLoaded', () => {
 const tabs=document.querySelectorAll('[data-tour-tab]'), panels=document.querySelectorAll('[data-tour-panel]'); tabs.forEach(tab=>tab.addEventListener('click',()=>{tabs.forEach(x=>x.classList.remove('is-active'));panels.forEach(x=>x.classList.remove('is-active'));tab.classList.add('is-active');document.querySelector(`[data-tour-panel="${tab.dataset.tourTab}"]`).classList.add('is-active')}));
 const category=document.getElementById('tour-category'), subcategory=document.getElementById('tour-subcategory'); category?.addEventListener('change',async()=>{subcategory.innerHTML='<option value="">Loading...</option>';const r=await fetch(`{{ route('admin.tours.subcategories') }}?category_id=${category.value}`);const items=await r.json();subcategory.innerHTML='<option value="">No subcategory</option>'+items.map(i=>`<option value="${i.id}">${i.name}</option>`).join('')});
 const templates={itinerary:'<div class="wmt-repeater-row" data-row><button type="button" data-remove-row>×</button><input placeholder="Step title"><input type="number" placeholder="Duration"><select><option value="">Unit</option><option value="minutes">Minutes</option><option value="hours">Hours</option><option value="days">Days</option></select><input placeholder="Icon"><textarea placeholder="Step description"></textarea></div>',package:'<div class="wmt-repeater-row wmt-package-row" data-row><button type="button" data-remove-row>×</button><input placeholder="Package name"><textarea placeholder="Package description"></textarea><input placeholder="Badge label, e.g. Top Choice"><label>Live <input type="hidden" value="0"><input type="checkbox" checked></label><label>Recommended <input type="hidden" value="0"><input type="checkbox"></label></div>',price:'<div class="wmt-repeater-row wmt-price-row" data-row><button type="button" data-remove-row>×</button><input type="number" placeholder="Package row #"><select><option value="shared">Shared vehicle</option><option value="private">Private vehicle</option></select><input placeholder="Vehicle label"><textarea placeholder="Vehicle inclusions and description"></textarea><input type="number" placeholder="Adult price"><input type="number" placeholder="Child price"><input type="number" placeholder="Child age from"><input type="number" placeholder="Child age to"><input type="number" placeholder="Infant price"><input type="number" placeholder="Infant age to"><input type="number" placeholder="Min guests"><input type="number" placeholder="Max guests"></div>',availability:'<div class="wmt-repeater-row" data-row><button type="button" data-remove-row>×</button><input type="date"><input type="time"><input type="number" placeholder="Capacity"><input type="number" placeholder="Cutoff hrs"><label>Blocked <input type="checkbox"></label></div>'};
 const fieldNames={itinerary:['title','duration','duration_unit','icon','description'],package:['name','description','badge_label','is_active','is_recommended'],price:['package_index','vehicle_type','vehicle_label','description','adult_price','child_price','child_min_age','child_max_age','infant_price','infant_max_age','minimum_guests','maximum_guests'],availability:['available_date','start_time','capacity','booking_cutoff_hours','is_blocked']};
 document.querySelectorAll('[data-add-row]').forEach(button=>button.addEventListener('click',()=>{const type=button.dataset.addRow, holder=document.getElementById(`${type}-rows`), index=holder.querySelectorAll('[data-row]').length, wrap=document.createElement('div');wrap.innerHTML=templates[type];const row=wrap.firstElementChild;row.querySelectorAll('input:not([type="hidden"]),select,textarea').forEach((input,i)=>{input.name=`${type==='itinerary'?'itineraries':type+'s'}[${index}][${fieldNames[type][i]}]`;if(input.type==='checkbox')input.value='1'});holder.append(row)}));
 document.addEventListener('click',e=>{if(e.target.matches('[data-remove-row]'))e.target.closest('[data-row]').remove()});
});
</script>
@endsection
